import math, functools
from fractions import Fraction
@functools.lru_cache(None)
def ham(a,b,c):
 n=a+b+c
 if n<3:return 0
 v=0
 for t in range(min(a,b,c)+1):
  if (a+b-c-t)%2:continue
  u=(a+b-c-t)//2;w=(b+c-a-t)//2;z=(a+c-b-t)//2
  if min(u,w,z)<0:continue
  l=u+w+z+t
  v+=Fraction(math.factorial(l-1)*2**t,2*math.factorial(u)*math.factorial(w)*math.factorial(z)*math.factorial(t))
 return int(v*math.factorial(a)*math.factorial(b)*math.factorial(c))
def poly(q,s):
 p=[1]
 for _ in range(q):
  pp=[0]*(len(p)+3)
  for i,v in enumerate(p):
   for j,c in enumerate([1,15,9,1]):pp[i+j]+=v*c
  p=pp
 for _ in range(s):p=[p[i] if i<len(p) else 0 for i in range(len(p)+1)] # unused
 return p

def cyc(q,s,b,c):
 p=poly(q,0)
 for _ in range(s):p=[(p[i] if i<len(p) else 0)+(p[i-1] if i else 0) for i in range(len(p)+1)]
 ans=q
 for i,pi in enumerate(p):
  for j in range(b+1):
   for k in range(c+1):ans+=pi*math.comb(b,j)*math.comb(c,k)*ham(i,j,k)
 return ans
for m in [6,9,12,15,18,24,30]:
 a=cyc(m//3,0,m,m);b=cyc(m//3,1,m,m-1)
 print(m,float(Fraction(b,a)), float(Fraction(b-a,a))*m*m,flush=True)

