import z3,itertools,time,networkx as nx,json

def search(q,seconds=60):
 n=q+4; X=range(1,4);Y=range(4,n);pairs=list(itertools.combinations(range(n),2))
 es={}
 for u,v in pairs:
  if u==0 and v in X:es[u,v]=z3.BoolVal(True)
  elif u==0 or (u in X and v in Y):es[u,v]=z3.Bool(f'e{u}_{v}')
  else:es[u,v]=z3.BoolVal(False)
 def E(u,v):return es[tuple(sorted((u,v)))]
 s=z3.Solver();s.set(timeout=10000)
 s.add(z3.PbGe([(E(0,y),1) for y in Y],3))
 # Both required decompositions, as embeddings into independent side plus copies of J.
 for name,J in [('tri',nx.complete_graph(3)),('path',nx.path_graph(4))]:
  B=[z3.Bool(name+'b'+str(i)) for i in range(n)]
  comp=[z3.Int(name+'c'+str(i)) for i in range(n)]
  pos=[z3.Int(name+'p'+str(i)) for i in range(n)]
  for i in range(n):s.add(comp[i]>=0,comp[i]<=i,pos[i]>=0,pos[i]<len(J))
  for u,v in pairs:
   adj=z3.Or(*[z3.And(pos[u]==a,pos[v]==b) for a,b in list(J.edges())+[(b,a) for a,b in J.edges()]])
   s.add(z3.Implies(E(u,v),z3.And(z3.Not(z3.And(B[u],B[v])),z3.Or(B[u],B[v],z3.And(comp[u]==comp[v],adj)))))
  # Distinct vertices in one component must have different positions.
  for u,v in pairs:s.add(z3.Implies(z3.And(z3.Not(B[u]),z3.Not(B[v]),comp[u]==comp[v]),pos[u]!=pos[v]))
 start=time.time();it=0
 while time.time()-start<seconds:
  result=s.check()
  if result!=z3.sat:return str(result),it
  mod=s.model();G=nx.Graph();G.add_nodes_from(range(n));G.add_edges_from((u,v) for u,v in pairs if z3.is_true(mod.eval(E(u,v),model_completion=True)))
  # Find a decomposition into independent set B and disjoint subgraphs of P3.
  p=z3.Solver();bs=[z3.Bool('B'+str(i)) for i in range(n)]
  for u,v in G.edges():p.add(z3.Or(z3.Not(bs[u]),z3.Not(bs[v])))
  for A in itertools.combinations(range(n),3):
   if G.subgraph(A).number_of_edges()==3:p.add(z3.Or(*[bs[u] for u in A]))
  for A in itertools.combinations(range(n),4):
   if nx.is_connected(G.subgraph(A)):p.add(z3.Or(*[bs[u] for u in A]))
  if p.check()!=z3.sat:
   return 'FOUND',it,sorted(G.edges())
  pm=p.model();B=[i for i in range(n) if z3.is_true(pm.eval(bs[i],model_completion=True))];A=[i for i in range(n) if i not in B]
  terms=[E(u,v) for u,v in itertools.combinations(B,2)]
  for vs in itertools.combinations(A,3):terms.append(z3.And(*[E(u,v) for u,v in itertools.combinations(vs,2)]))
  for vs in itertools.combinations(A,4):
   for edgeinds in itertools.combinations(list(itertools.combinations(vs,2)),3):
    T=nx.Graph();T.add_nodes_from(vs);T.add_edges_from(edgeinds)
    if nx.is_tree(T):terms.append(z3.And(*[E(u,v) for u,v in edgeinds]))
  s.add(z3.Or(*terms));it+=1
 return 'TIME',it
for q in range(3,10):
 res=search(q,60)
 print(q,res,flush=True)
 if res[0]=='FOUND':
  json.dump(res,open('apex_found.json','w'));break

