  s.add(z3.Implies(es[u,v],z3.And(z3.Not(z3.And(B[u],B[v])),z3.Or(B[u],B[v],z3.And(comp[u]==comp[v],adj)))))
  s.add(z3.Implies(z3.And(z3.Not(B[u]),z3.Not(B[v]),comp[u]==comp[v]),pos[u]!=pos[v]))
 return B

