 fork=nx.Graph([(0,1),(0,2),(0,3),(3,4)])
 for name,J in [('tri',nx.complete_graph(3)),('C4',nx.cycle_graph(4)),('P5',nx.path_graph(5)),('fork',fork)]:witness(s,es,n,name,J)
